// Station -> code against RoboDK 5.9.4's own MakeProgram (tests/fixtures/robodk_gt/code/robodk_generated_code.tgz):
// a RoboDK Library station is imported (C:/RoboDK/Library), each program RoboDK generated is compiled with
// compileForPost and post-processed with the robot's post (the Export dialog's default), and every file RoboDK wrote is
// compared line by line. Tolerances: date / "generated by" lines and blank lines ignored, numbers within `tol`.
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { gunzipSync } from 'node:zlib';
import { importRdkBestEffort } from '../src/io/robodk/rdk_container';
import { AssetStore } from '../src/scene/assets';
import { Station, ItemType } from '../src/core/items/item';
import { Robot } from '../src/core/items/robot';
import { Program } from '../src/core/items/program';
import { compileForPost, getPost, PostFile, CompileOptions } from '../src/posts/index';
import { normLines, tokens } from './posts_gt_util';

export const LIB = 'C:/RoboDK/Library';
const GT_TGZ = path.resolve(__dirname, 'fixtures/robodk_gt/code/robodk_generated_code.tgz');

let gtCache: Map<string, Buffer> | null = null;
/** RoboDK's generated code: "<station>.rdk_/<program>/<file>" -> bytes. */
export function gtCode(): Map<string, Buffer> {
  if (gtCache) return gtCache;
  const tar = gunzipSync(readFileSync(GT_TGZ)), out = new Map<string, Buffer>();
  let longName: string | null = null;   // PAX "path" / GNU long name of the next entry
  for (let off = 0; off + 512 <= tar.length;) {
    let name = tar.subarray(off, off + 100).toString('utf8').replace(/\0.*$/s, '');
    if (!name) break;
    const prefix = tar.subarray(off + 345, off + 500).toString('utf8').replace(/\0.*$/s, '');
    if (prefix) name = `${prefix}/${name}`;
    const size = parseInt(tar.subarray(off + 124, off + 136).toString('utf8').replace(/\0.*$/s, '').trim() || '0', 8);
    const type = String.fromCharCode(tar[off + 156]);
    const data = tar.subarray(off + 512, off + 512 + size);
    if (type === 'x') { const m = data.toString('utf8').match(/\d+ path=([^\n]*)\n/); if (m) longName = m[1]; }
    else if (type === 'L') longName = data.toString('utf8').replace(/\0.*$/s, '');
    else {
      if (type === '0' || type === '\0') out.set((longName ?? name).replace(/^\.\//, ''), data);
      longName = null;
    }
    off += 512 + Math.ceil(size / 512) * 512;
  }
  return (gtCache = out);
}
/** The GT folder name RoboDK used for a Library file. */
export const gtStationDir = (file: string) => `${file.replace(/[^A-Za-z0-9.-]/g, '_')}_`;

export async function loadLibraryStation(file: string): Promise<Station> {
  const b = readFileSync(`${LIB}/${file}`);
  const { station } = await importRdkBestEffort(b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength), file, new AssetStore());
  return station;
}

/** Tolerant line equality: case-insensitive text tokens, numbers within tol. */
export function sameLine(a: string, b: string, tol: number): boolean {
  const ta = tokens(a.toLowerCase()), tb = tokens(b.toLowerCase());
  return ta.length === tb.length && ta.every((t, k) => (typeof t === 'number' && typeof tb[k] === 'number' ? Math.abs(t - (tb[k] as number)) <= tol : t === tb[k]));
}
/** First differing line (null = equal). */
export function diffTolerant(expected: string, actual: string, tol = 0.011): string | null {
  const a = normLines(expected), b = normLines(actual);
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    if (a[i] === undefined || b[i] === undefined) return `line ${i + 1}: expected "${a[i] ?? '<end>'}" got "${b[i] ?? '<end>'}"`;
    if (!sameLine(a[i], b[i], tol)) return `line ${i + 1}: expected "${a[i]}" got "${b[i]}"`;
  }
  return null;
}

export interface CodeCase { program: string; file: string; status: 'equal' | 'diff' | 'missing' | 'no-program' | 'skipped'; detail?: string; post?: string }

/** Generate a station's programs with their robots' posts and compare them with RoboDK's code. */
/** RoboDK's default post for a robot without one (RoboDK picks the brand's post): by the extension RoboDK wrote. */
const BY_EXT: Record<string, string> = { '.src': 'KUKA_KRC2', '.mod': 'ABB_RAPID_IRC5', '.ls': 'Fanuc_R30i', '.pdl': 'Comau_C5G', '.jbi': 'Motoman', '.script': 'Universal_Robots', '.pg': 'Kawasaki' };

export async function compareStationCode(file: string, only?: string[], tol = 0.011, copts: CompileOptions = {}): Promise<CodeCase[]> {
  const station = await loadLibraryStation(file);
  const dir = gtStationDir(file);
  const gt = gtCode();
  const progs = new Map<string, string[]>();
  for (const k of gt.keys()) if (k.startsWith(dir + '/')) { const [, prog, f] = k.split('/'); if (prog && f) progs.set(prog, [...(progs.get(prog) ?? []), f]); }
  const out: CodeCase[] = [];
  const norm = (s: string) => s.replace(/[^A-Za-z0-9]/g, '').toLowerCase();
  for (const [prog, files] of progs) {
    if (only && !only.includes(prog)) continue;
    const p = station.itemsOfType<Program>(ItemType.PROGRAM).find((x) => x.name === prog || norm(x.name) === norm(prog));
    if (!p) { out.push({ program: prog, file: files.join(','), status: 'no-program' }); continue; }
    const robot = p.robot();
    const own = robot instanceof Robot ? robot.postProcessor : '';
    const ext = path.extname(files.find((f) => !/\.(txt|urp)$/i.test(f)) ?? '').toLowerCase();
    const post = (own && own !== 'Generic' ? getPost(own) : getPost(BY_EXT[ext] ?? '')) ?? null;
    if (files.every((f) => gt.get(`${dir}/${prog}/${f}`)!.toString('latin1').includes('Invalid license or undefined post processor'))) { out.push({ program: prog, file: files.join(','), status: 'skipped', detail: 'RoboDK wrote a license placeholder (mechanism without post)' }); continue; }
    if (!post) { out.push({ program: prog, file: files.join(','), status: 'missing', detail: `no post for ${robot instanceof Robot ? robot.postProcessor : '-'}` }); continue; }
    let gen: PostFile[] = [];
    try { gen = post.generate(compileForPost(station, p, copts)); } catch (e: any) { out.push({ program: prog, file: files.join(','), status: 'missing', detail: `post failed: ${e.message}`, post: post.id }); continue; }
    for (const f of files) {
      if (/\.urp$/i.test(f)) continue;
      const mine = gen.find((g) => g.name.toLowerCase() === f.toLowerCase()) ?? gen.find((g) => norm(g.name) === norm(f));
      if (!mine) { out.push({ program: prog, file: f, status: 'missing', detail: `studio wrote ${gen.map((g) => g.name).join(',')}`, post: post.id }); continue; }
      const d = diffTolerant(gt.get(`${dir}/${prog}/${f}`)!.toString('latin1'), mine.content, tol);
      out.push({ program: prog, file: f, status: d ? 'diff' : 'equal', detail: d ?? undefined, post: post.id });
    }
  }
  return out;
}
export const haveLibrary = (file: string) => existsSync(`${LIB}/${file}`) && existsSync(GT_TGZ);
